// Render pipeline of the code generator (see docs/design-notes.md#codegen): ejs → Prettier (parser by file type) → the
// `@generated` header → output. Generator input is untrusted, so templates never print a value raw:
// `<%- %>` is refused by scripts/arch/ejs-lint.mjs (only `include(…)` may use it) and every `<%= %>`
// goes through `emit`, which prints numbers, booleans, identifier-like tokens and `Code` built by the
// helpers below (string literals, JSON, comment text), and throws on anything else.
import { readFileSync } from 'node:fs'
import { extname, join } from 'node:path'
import ejs from 'ejs'
import { format, resolveConfig } from 'prettier'
import { codegenTemplatesDir } from '../../../core/paths.js'

/** Text that is safe to print as is: made by the helpers (or model code) from checked input only. */
export class Code {
  constructor(readonly text: string) {}
  toString(): string {
    return this.text
  }
}

/**
 * A plain token: identifiers, i18n keys, route paths, icons (`lucide:x`), perm strings. No quotes,
 * spaces, backslashes, line breaks or `<>`, so it can't leave a string literal, attribute or comment;
 * `//` and `/*` could open a comment.
 */
const TOKEN = /^[\w$.:/@-]*$/
const OPENS_COMMENT = /\/\/|\/\*|\*\//

/** `<%= value %>`: Code as is, numbers/booleans/plain tokens as text; anything else is a template bug. */
export function emit(value: unknown): string {
  if (value instanceof Code) return value.text
  if (typeof value === 'number' && Number.isFinite(value)) return String(value)
  if (typeof value === 'boolean') return String(value)
  if (typeof value === 'string' && TOKEN.test(value) && !OPENS_COMMENT.test(value)) return value
  throw new Error(
    `codegen: unsafe value in <%= %> (use str(), comment() or json()): ${String(JSON.stringify(value)).slice(0, 60)}`,
  )
}

/**
 * A string literal of any text (DB comments, labels): JSON escaping, plus `<` as `<` (no `</script>`
 * inside a .vue file) and the line/paragraph separators escaped.
 */
export const str = (text: string): Code =>
  new Code(
    JSON.stringify(String(text))
      .replace(/</g, '\\u003c')
      .replace(/\u2028/g, '\\u2028')
      .replace(/\u2029/g, '\\u2029'),
  )

/** `value` as JSON (a locale fragment); Prettier formats it afterwards. */
export const json = (value: unknown): Code => new Code(JSON.stringify(value, null, 2))

const COMMENT_MARKS = /\*\/|\/\*|<!--|-->|--!>/g
/**
 * Text for inside a `//`, `/** *\/` or `<!-- -->` comment: one line (line breaks become spaces), with
 * every comment opener/closer removed until none is left (`*\/*\/` would otherwise rejoin).
 */
export function comment(text: string): Code {
  let s = String(text).replace(/[\r\n\u2028\u2029]+/g, ' ')
  for (let prev = ''; prev !== s;) {
    prev = s
    s = s.replace(COMMENT_MARKS, '')
  }
  return new Code(s.replace(/\s+/g, ' ').trim())
}

const IMPORT_NAME = /^(type )?[A-Za-z_$][\w$]*$/
/**
 * Named imports `a, type B, c` in the repository's order: by name ignoring `type` and case, the
 * upper-case one first on a tie. Falsy entries (a template's `cond && 'x'`) are left out.
 */
export function names(list: (string | false | undefined)[]): Code {
  const key = (n: string) => n.replace(/^type /, '')
  const set = [...new Set(list.filter((n): n is string => !!n))]
  for (const n of set) if (!IMPORT_NAME.test(n)) throw new Error(`codegen: bad import name ${n}`)
  const cmp = (x: string, y: string) => (x < y ? -1 : x > y ? 1 : 0)
  set.sort((a, b) => cmp(key(a).toLowerCase(), key(b).toLowerCase()) || cmp(key(a), key(b)))
  return new Code(set.join(', '))
}

/** The template helpers every template gets besides its model. */
export const helpers = { str, json, comment, names }

/** One template's output before formatting. */
export function renderSource(
  source: string,
  locals: Record<string, unknown>,
  filename = 'inline.ejs',
): string {
  const data = { ...helpers, ...locals }
  return ejs.render(source, data, {
    filename,
    strict: true,
    destructuredLocals: Object.keys(data),
    escape: emit,
  })
}

const PARSERS: Record<string, string> = {
  '.ts': 'typescript',
  '.vue': 'vue',
  '.json': 'json',
}

/** The generated-file marker `codegen:report` looks for (see docs/design-notes.md#codegen); JSON has no comments. */
export function header(path: string, template: string): string {
  const mark = `@generated by qw-codegen (${template})`
  const ext = extname(path)
  if (ext === '.vue') return `<!-- ${mark} -->\n`
  if (ext === '.json') return ''
  return `// ${mark}\n`
}

/**
 * Prettier with the repository's config (found from the working directory, `apps/server`, like every
 * runtime path), then the header on the first line.
 * Outside the repo (no .prettierrc above cwd) Prettier's defaults apply; ship the config with
 * dist if the generator ever runs from a deployed build.
 */
export async function finish(code: string, path: string, template: string): Promise<string> {
  const parser = PARSERS[extname(path)]
  if (!parser) throw new Error(`codegen: no formatter for ${path}`)
  const config = (await resolveConfig(join(process.cwd(), 'package.json'))) ?? {}
  return header(path, template) + (await format(code, { ...config, parser }))
}

export interface RenderedFile {
  /** repository-relative output path */
  path: string
  content: string
}

/** A template file (`server/entity.ts.ejs`) of `codegen-templates/` and where its output goes. */
export interface Target {
  template: string
  path: string
  /** extra locals of this output (e.g. the language of a locale fragment) */
  locals?: Record<string, unknown>
}

/** Renders `targets` with `locals` through the whole pipeline; `kind` names the template set (`crud`). */
export async function renderTargets(
  targets: Target[],
  locals: Record<string, unknown>,
  kind: string,
): Promise<RenderedFile[]> {
  const dir = codegenTemplatesDir()
  const out: RenderedFile[] = []
  for (const t of targets) {
    const file = join(dir, t.template)
    const code = renderSource(readFileSync(file, 'utf8'), { ...locals, ...t.locals }, file)
    out.push({ path: t.path, content: await finish(code, t.path, kind) })
  }
  return out
}
